namespace BookingMgmt.Domain.DomainServicesImplementations
{
    public class BookingCreatorDomainServices : IBookingCreatorDomainServices
    {
        private const bool TrackingStateForEdit = true;

        private readonly IUnitOfWorkBookingCreator _unitOfWorkBookingCreator;
        private readonly IRepository<Booking> _bookingRepository;
        private readonly IRepository<Journey> _journeyRepository;
        private readonly IBookingCreatorValidations _bookingCreatorValidations;

        public BookingCreatorDomainServices(
            IUnitOfWorkBookingCreator unitOfWorkBookingCreator,
            IBookingCreatorValidations bookingCreatorValidations)
        {
            _unitOfWorkBookingCreator = unitOfWorkBookingCreator;
            _bookingCreatorValidations = bookingCreatorValidations;

            _bookingRepository = _unitOfWorkBookingCreator.GetRepository<Booking>();
            _journeyRepository = _unitOfWorkBookingCreator.GetRepository<Journey>();
        }

        public void CancelBooking(int bookingId)
        {
            var booking = GetValidBooking(bookingId);

            _bookingCreatorValidations.Validate(booking);

            RemoveJourneys(booking);

            UpdateModificationDate(booking);

            _unitOfWorkBookingCreator.Save();
        }

        public int CreateBooking(Booking booking)
        {
            _bookingCreatorValidations.Validate(booking);
            booking.AddRecordLocator();
            booking.UpdateCreationDate();
            booking.UpdateModifiedDate();
            _bookingRepository.Insert(booking);
            _unitOfWorkBookingCreator.Save();
            return booking.Id;
        }


        public IQueryable<Booking> GetCanceled()
        {
            return _bookingRepository.Get(
                filter: x => !x.Journeys.Any(),
                orderBy: null,
                includeProperties: new List<Expression<Func<Booking, object>>>
                {
                    z => z.Journeys
                },
                page: null,
                pageSize: null
            );
        }

        public IQueryable<Booking> GetActives()
        {
            return _bookingRepository.Get(
                filter: x => x.Journeys.Any(),
                orderBy: null,
                includeProperties: new List<Expression<Func<Booking, object>>>
                {
                    z => z.Journeys
                },
                page: null,
                pageSize: null
            );
        }

        private Booking GetValidBooking(int bookingId)
        {
            return _bookingRepository.Get(
                    filter: x => x.Id == bookingId,
                    orderBy: null,
                    includeProperties:
                        new List<Expression<Func<Booking, object>>>
                            {
                                z => z.Journeys
                            },
                    page: null,
                    pageSize: null,
                    trackingEnabled: TrackingStateForEdit
                ).SingleOrDefault();
        }


        private void RemoveJourneys(Booking booking)
        {
            foreach (var journey in booking.Journeys.ToList())
            {
                _journeyRepository.Delete(journey);
            }
        }

        private void UpdateModificationDate(Booking booking)
        {
            booking.Modified = DateTime.UtcNow;

            _bookingRepository.UpdateRootEntity(booking);
        }

    }
}

namespace BookingMgmt.Domain.DomainServicesImplementations
{
    public class BookingFeaturesDomainServices : IBookingFeaturesDomainServices
    {

        public bool IsEnabledToAddNewJourneys(Booking booking)
        {
            return booking.Journeys == null || 
                   booking.Journeys.Count < 15;
        }

        public bool IsAgency(Booking booking)
        {
            return !string.IsNullOrEmpty(booking.SalesAgent) && 
                   booking.SalesAgent.Equals("Agency", StringComparison.InvariantCultureIgnoreCase);
        }

        public bool IsCorporate(Booking booking)
        {
            return !string.IsNullOrEmpty(booking.SalesAgent) && 
                   booking.SalesAgent.Equals("Corporate", StringComparison.InvariantCultureIgnoreCase);
        }
    }
}

namespace BookingMgmt.Domain.Entities
{
    public class Booking
    {
        public Booking()
        {
            Created = DateTime.UtcNow;
            UpdateModifiedDate();
        }

        public int Id { get; set; }
        public string SalesAgent { get; set; }
        public DateTime Created { get; set; }
        public DateTime Modified { get; set; }

        string _recordLocator;
        public string RecordLocator
        {
            get => _recordLocator;
            set
            {
                UpdateModifiedDate();
                _recordLocator = value;
            }
        }

        public virtual ICollection<Journey> Journeys { get; set; }
        public virtual ICollection<Passenger> Passengers { get; set; }

        public string GetRoute()
        {
            if (Journeys == null || Journeys.Count == 0) { return string.Empty; }

            var firstJourney = Journeys.OrderBy(x => x.DepartureDate).First();
            var lastJourney = Journeys.OrderBy(x => x.DepartureDate).Last();

            return $"{firstJourney.Departure}{lastJourney.Arrival}";
        }

        public void AddJourney(Journey journey)
        {
            ValidateNewJourney(journey);

            if (Journeys == null) { Journeys = new HashSet<Journey>(); }

            Journeys.Add(journey);

            UpdateModifiedDate();
        }

        public void AddPassenger(Passenger passenger)
        {
            ValidateNewPassenger(passenger);

            if (Passengers == null) { Passengers = new HashSet<Passenger>(); }

            EnsurePaxType(passenger);

            Passengers.Add(passenger);

            UpdateModifiedDate();
        }

        public void AddRecordLocator()
        {
            RecordLocator = Guid.NewGuid().ToString();
        }

        public decimal GetTotalPrice()
        {
            return !Journeys.Any() ? default : Journeys.Sum(x => x.Price);
        }

        public bool IsAlreadyFlew()
        {
            return Journeys != null && !Journeys.Any(x => x.DepartureDate > DateTime.UtcNow);
        }

        private static void EnsurePaxType(Passenger passenger)
        {
            if (passenger.PaxType == Passenger.PassengerType.Unassigned) { passenger.PaxType = Passenger.PassengerType.ADU; }
        }

        private void ValidateNewJourney(Journey journey)
        {
            if (journey == null) { throw new ArgumentNullException("journey"); }
            if (string.IsNullOrEmpty(journey.Departure) || string.IsNullOrEmpty(journey.Arrival)) { throw new ArgumentException("Paremeters Departure and Arrival are required to add new journey."); }
        }

        private void ValidateNewPassenger(Passenger passenger)
        {
            if (passenger == null) { throw new ArgumentNullException("passenger"); }
            if (string.IsNullOrEmpty(passenger.FullName)) { throw new ArgumentException("Paremeter FullName is required to add new passenger."); }
        }

        public void UpdateModifiedDate()
        {
            Modified = DateTime.UtcNow;
        }

        public void UpdateCreationDate()
        {
            Created = DateTime.UtcNow;
        }

    }
}

